// C side of tests/run/ffi.ax. Freestanding (no libc): it is also compiled
// for wasm32 and linked into the same module.
#include <stdarg.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

#include "ffi_generated.h"  // generated by axiom --emit-header

int32_t c_add(int32_t a, int32_t b) { return a + b; }
double c_scale(double x, double k) { return x * k; }

uint32_t c_sum_bytes(const uint8_t *p, size_t n) {
    uint32_t s = 0;
    for (size_t i = 0; i < n; i++) s += p[i];
    return s;
}

int8_t c_neg8(int8_t x) { return (int8_t)-x; }
uint16_t c_hi16(uint32_t x) { return (uint16_t)(x >> 16); }
bool c_is_even(int32_t x) { return x % 2 == 0; }

int64_t c_sum_ints(int32_t n, ...) {
    va_list ap;
    va_start(ap, n);
    int64_t s = 0;
    for (int32_t i = 0; i < n; i++) s += va_arg(ap, int64_t);
    va_end(ap);
    return s;
}

double c_avg(int32_t n, ...) {
    va_list ap;
    va_start(ap, n);
    double s = 0;
    for (int32_t i = 0; i < n; i++) s += va_arg(ap, double);
    va_end(ap);
    return s / n;
}

// Calls back into Axiom through a function pointer.
int32_t c_apply(int32_t (*f)(int32_t), int32_t x) { return f(x) + 1; }

// Uses the Axiom struct through the generated header.
void c_fill_point(Point *p) {
    p->x = 7;
    p->y = 2.5;
    p->flag = true;
    p->id = 65535;
}

// Calls exported Axiom functions directly, by name.
int32_t c_calls_axiom(int32_t x) { return ax_triple(x) + ax_small(-3); }

const char *c_greeting(void) { return "hello from C"; }
void *c_null(void) { return 0; }
